def install_guards() -> None:
    op.execute("""
    CREATE FUNCTION guard_agent_version() RETURNS trigger LANGUAGE plpgsql AS $$
    BEGIN
        IF TG_OP IN ('UPDATE', 'DELETE') AND OLD.status = 'snapshot' THEN
            RAISE EXCEPTION 'Immutable snapshot' USING ERRCODE = '23514';
        END IF;
        IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
        IF TG_OP = 'INSERT' AND NEW.status <> 'draft' THEN
            RAISE EXCEPTION 'Versions must start as drafts' USING ERRCODE = '23514';
        END IF;
        IF TG_OP = 'UPDATE' AND
          ROW(NEW.agent_id, NEW.number, NEW.created_by, NEW.source_version)
          IS DISTINCT FROM ROW(OLD.agent_id, OLD.number, OLD.created_by, OLD.source_version) THEN
            RAISE EXCEPTION 'Immutable version identity' USING ERRCODE = '23514';
        END IF;
        PERFORM id FROM models WHERE id = NEW.model_id AND status = 'approved' FOR SHARE;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'Model must be approved' USING ERRCODE = '23514';
        END IF;
        IF NEW.configuration #>> '{model,model_id}' IS DISTINCT FROM NEW.model_id OR
           NEW.configuration->'security' IS DISTINCT FROM
           '{"require_authentication": true,"resource_scope": "caller_owned",
             "allow_financial_writes": false}'::jsonb THEN
            RAISE EXCEPTION 'Invalid model reference or policy' USING ERRCODE = '23514';
        END IF;
        IF NEW.status = 'snapshot' THEN
            IF NEW.snapshot->'configuration' IS DISTINCT FROM NEW.configuration THEN
                RAISE EXCEPTION 'Snapshot configuration mismatch' USING ERRCODE = '23514';
            END IF;
            IF EXISTS (
                SELECT 1 FROM agent_tools b JOIN tools t ON t.id = b.tool_id
                JOIN agents a ON a.id = b.agent_id JOIN users u ON u.id = a.owner_id
                WHERE b.agent_id = NEW.agent_id AND b.version_number = NEW.number
                AND (t.status <> 'approved' OR t.operation <> 'read'
                     OR NOT t.permissions <@ u.permissions)
            ) THEN
                RAISE EXCEPTION 'Tool not approved or authorized' USING ERRCODE = '23514';
            END IF;
        END IF;
        RETURN NEW;
    END $$
    """)
    op.execute("""
    CREATE FUNCTION guard_agent_tool() RETURNS trigger LANGUAGE plpgsql AS $$
    DECLARE parent_status text; permission_grants jsonb;
    BEGIN
        IF TG_OP = 'UPDATE' AND ROW(NEW.agent_id, NEW.version_number, NEW.tool_id)
           IS DISTINCT FROM ROW(OLD.agent_id, OLD.version_number, OLD.tool_id) THEN
            RAISE EXCEPTION 'Replace draft bindings using delete and insert'
                USING ERRCODE = '23514';
        END IF;
        IF TG_OP IN ('UPDATE', 'DELETE') THEN
            SELECT status INTO parent_status FROM agent_versions
             WHERE agent_id = OLD.agent_id AND number = OLD.version_number FOR UPDATE;
            IF parent_status = 'snapshot' THEN
                RAISE EXCEPTION 'Immutable snapshot tools' USING ERRCODE = '23514';
            END IF;
        END IF;
        IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
        SELECT status INTO parent_status FROM agent_versions
         WHERE agent_id = NEW.agent_id AND number = NEW.version_number FOR UPDATE;
        IF parent_status = 'snapshot' THEN
            RAISE EXCEPTION 'Immutable snapshot tools' USING ERRCODE = '23514';
        END IF;
        SELECT u.permissions INTO permission_grants FROM users u JOIN agents a ON a.owner_id = u.id
         WHERE a.id = NEW.agent_id;
        PERFORM id FROM tools WHERE id = NEW.tool_id AND status = 'approved'
            AND operation = 'read' AND permissions <@ permission_grants FOR SHARE;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'Tool not approved or authorized' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END $$
    """)
    op.execute("""
    CREATE FUNCTION check_agent_bindings() RETURNS trigger LANGUAGE plpgsql AS $$
    DECLARE aid text; ver integer; config jsonb; actual jsonb;
    BEGIN
        IF TG_OP = 'DELETE' THEN aid := OLD.agent_id; ELSE aid := NEW.agent_id; END IF;
        IF TG_TABLE_NAME = 'agent_versions' THEN
            IF TG_OP = 'DELETE' THEN ver := OLD.number;
            ELSE ver := NEW.number; END IF;
        ELSE
            IF TG_OP = 'DELETE' THEN ver := OLD.version_number;
            ELSE ver := NEW.version_number; END IF;
        END IF;
        SELECT configuration INTO config FROM agent_versions WHERE agent_id = aid AND number = ver;
        IF NOT FOUND THEN RETURN NULL; END IF;
        SELECT COALESCE(jsonb_agg(tool_id ORDER BY tool_id), '[]'::jsonb) INTO actual
            FROM agent_tools WHERE agent_id = aid AND version_number = ver;
        IF config->'tool_ids' IS DISTINCT FROM actual THEN
            RAISE EXCEPTION 'Tool relationships must match configuration' USING ERRCODE = '23514';
        END IF;
        RETURN NULL;
    END $$
    """)
    op.execute("""
    CREATE FUNCTION guard_agent_owner() RETURNS trigger LANGUAGE plpgsql AS $$
    BEGIN
        IF NEW.owner_id <> OLD.owner_id AND EXISTS (
            SELECT 1 FROM agent_versions WHERE agent_id = OLD.id AND status = 'snapshot'
        ) THEN
            RAISE EXCEPTION 'Snapshot ownership is fixed' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END $$
    """)
    op.execute("""
    CREATE FUNCTION immutable_catalog_definition() RETURNS trigger LANGUAGE plpgsql AS $$
    BEGIN
        IF (to_jsonb(NEW) - 'status') IS DISTINCT FROM (to_jsonb(OLD) - 'status') THEN
            RAISE EXCEPTION 'Create a new catalog version to change its definition'
                USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END $$
    """)
    for statement in [
        "CREATE TRIGGER guard_version BEFORE INSERT OR UPDATE OR DELETE ON agent_versions "
        "FOR EACH ROW EXECUTE FUNCTION guard_agent_version()",
        "CREATE TRIGGER guard_binding BEFORE INSERT OR UPDATE OR DELETE ON agent_tools "
        "FOR EACH ROW EXECUTE FUNCTION guard_agent_tool()",
        "CREATE CONSTRAINT TRIGGER consistent_version AFTER INSERT OR UPDATE ON agent_versions "
        "DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION check_agent_bindings()",
        "CREATE CONSTRAINT TRIGGER consistent_binding "
        "AFTER INSERT OR UPDATE OR DELETE ON agent_tools "
        "DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION check_agent_bindings()",
        "CREATE TRIGGER guard_owner BEFORE UPDATE ON agents "
        "FOR EACH ROW EXECUTE FUNCTION guard_agent_owner()",
        "CREATE TRIGGER immutable_model_definition BEFORE UPDATE ON models "
        "FOR EACH ROW EXECUTE FUNCTION immutable_catalog_definition()",
        "CREATE TRIGGER immutable_tool_definition BEFORE UPDATE ON tools "
        "FOR EACH ROW EXECUTE FUNCTION immutable_catalog_definition()",
    ]:
        op.execute(statement)
